$ cat Stacks.java
public class Stacks {
    static void deep(int n) { if (n > 0) { long a=1,b=2,c=3,d=4,e=5,f=6,g=7,h=8;
                                           deep(n-1); ... } }
    public static void main(String[] a) throws Exception {
        int n = Integer.parseInt(a[0]);
        boolean recurse = a[1].equals("deep");
        for (int i = 0; i < n; i++) {
            Thread t = new Thread(() -> {
                if (recurse) deep(3000);       // 스택을 깊이 쓴다
                try { Thread.sleep(60000); } catch (Exception e) {}
            });
            t.setDaemon(true); t.start();
        }
        Thread.sleep(60000);
    }
}

